def project_unitary(theta: float, phi: float) -> tuple[float, float]:
    import numpy as np
    phi_sin = 2.0 * np.sin(theta)
    if abs(phi) <= abs(phi - phi_sin):
        return theta, 0.0
    else:
        return theta, phi_sin

def defect(theta: float, phi: float) -> float:
    import numpy as np
    return phi**2 - 2 * phi * np.sin(theta)
